<footer>Sun Son Solar · Secure service workspace</footer></main>
<script>
const calendarStyles=document.createElement('link');calendarStyles.rel='stylesheet';calendarStyles.href='<?= base_url('assets/calendar.css') ?>';document.head.appendChild(calendarStyles);const availabilityStyles=document.createElement('link');availabilityStyles.rel='stylesheet';availabilityStyles.href='<?= base_url('assets/availability.css') ?>';document.head.appendChild(availabilityStyles);
document.querySelectorAll('.geo-form').forEach(form=>form.addEventListener('submit',event=>{if(form.dataset.ready==='yes')return;event.preventDefault();const status=form.querySelector('.geo-status');if(!navigator.geolocation){status.textContent='GPS is unavailable; check-in can continue without coordinates.';form.dataset.ready='yes';form.requestSubmit();return;}status.textContent='Requesting site location…';navigator.geolocation.getCurrentPosition(position=>{form.querySelector('[name=latitude]').value=position.coords.latitude;form.querySelector('[name=longitude]').value=position.coords.longitude;form.dataset.ready='yes';form.requestSubmit();},()=>{status.textContent='Location permission was not granted; recording check-in without coordinates.';form.dataset.ready='yes';form.requestSubmit();},{enableHighAccuracy:true,timeout:10000,maximumAge:0});}));
document.querySelectorAll('.restore-form').forEach(form=>form.addEventListener('submit',event=>{if(!confirm('Restore this backup? Existing records with the same IDs will be updated.'))event.preventDefault();}));
</script></body></html>
